<div class="page-head"><div><a class="sub" href="/admin/mailboxes">← Správa schránek</a><h1 style="margin-top:8px"><?=\App\Core\View::e($mailbox['display_name'])?></h1><div class="sub"><?=\App\Core\View::e($mailbox['localpart'])?>@<?=\App\Core\View::e($domain)?></div></div></div><div class="card tablewrap"><table class="table"><tr><th>Datum</th><th>Směr</th><th>Od</th><th>Komu</th><th>Předmět</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=\App\Core\View::e(date('d.m.Y H:i',strtotime($r['created_at'])))?></td><td><?=($r['direction']==='inbound'?'Přijatý':'Odeslaný')?></td><td><?=\App\Core\View::e($r['from_email'])?></td><td><?=\App\Core\View::e($r['to_email'])?></td><td><a href="/admin/mailboxes/<?=$mailbox['id']?>/message/<?=$r['id']?>"><b><?=\App\Core\View::e($r['subject'])?></b></a></td><td><?=((int)$r['attachment_count'])?> příloh</td></tr><?php endforeach;if(!$rows):?><tr><td colspan="6" class="sub">Schránka je zatím prázdná.</td></tr><?php endif;?></table></div><div class="card" style="margin-top:16px"><h3>Nový e-mail</h3><form class="form" method="post" action="/admin/mailboxes/<?=$mailbox['id']?>/send"><input type="hidden" name="_csrf" value="<?=App\Core\Auth::csrf()?>"><div class="field"><label>Komu</label><input type="email" name="to" required></div><div class="field"><label>Předmět</label><input name="subject" required></div><div class="field"><label>Zpráva</label><textarea name="body" rows="8" required></textarea></div><button class="btn primary">Odeslat</button></form></div>